"use strict";exports.id=452,exports.ids=[452],exports.modules={50452:(a,b,c)=>{c.r(b),c.d(b,{toolDetails:()=>d});let d={id:"util-password",slug:"password-generator",category:"utility",categoryName:"Utility Tools",title:"Secure Password Generator",shortDesc:"Create cryptographically secure, random passwords with custom rules.",metaDesc:"Generate secure, random passwords online. Customize length, letters, numbers, symbols. Cryptographically secure client-side generation.",instructions:["Choose your password length (recommended 12-24 characters).","Toggle parameters: Uppercase, Lowercase, Numbers, and Symbols.","Click 'Generate Password'.","Copy the result and view the strength evaluation indicator."],features:["Uses cryptographically secure `crypto.getRandomValues`.","Calculates password entropy strength scores.","Privacy-first: No generation variables are saved or transmitted."],componentName:"PasswordGenerator",faqs:[{question:"What makes a strong password?",answer:"A strong password is long, randomized, and complex. It should contain at least 12 to 16 characters and combine uppercase letters, lowercase letters, numbers, and special symbols. Strong passwords do not include common words, dictionary phrases, birthdates, or easily guessable personal details."},{question:"Why should I use a password generator?",answer:"You should use a password generator because humans are naturally poor at creating truly random strings. Generated passwords eliminate predictable keyboard patterns and dictionary words, creating high-entropy keys that protect your email, bank, and social accounts from automated brute-force hacker attacks."},{question:"How long should a secure password be?",answer:"A secure password should be at least 12 characters long, though 16 or more is recommended for administrator accounts. Each additional character increases the cryptographic entropy exponentially, making it virtually impossible for supercomputers to crack your passwords within a reasonable timeframe."},{question:"Are generated passwords random?",answer:"Yes, our tool generates passwords using your browser's native Web Cryptography API (`crypto.getRandomValues`). Unlike standard random functions, this cryptographic algorithm produces cryptographically strong, non-predictable values, ensuring your passwords meet strict security standards."},{question:"Should I reuse passwords across websites?",answer:"No, you should never reuse passwords across websites. If one website suffers a security breach, hackers will try your compromised email and password combination on dozens of other platforms, including banks and social media. Using unique passwords for every site protects your accounts from credential stuffing."}],seoTitle:"Secure Password Generator - Create Strong Random Keys",seoHeading:"Generate Strong, Cryptographically Secure Passwords",seoIntro:"Keep accounts safe from dictionary attacks. Create randomized, high-entropy passwords with custom length thresholds.",seoBody:"\n<h3>Importance of High-Entropy Passwords</h3>\n<p>Weak passwords are the single largest source of security breaches. Using randomized combinations of letters, numbers, and symbols prevents automated brute-force scripts from hacking your cloud accounts, shops, and social logins.</p>\n    "}}};